using System;using System.Drawing;using System.Windows.Forms;
namespace Synkoz {public static class MusicalTimeR11 {public const int PPQ=96;public static double Beat(Montage m,double time){var c=TimelineMusicR11.Get(m);return c.Available?c.Beat(time):time*2;}public static double Time(Montage m,double beat){var c=TimelineMusicR11.Get(m);return c.Available?c.Time(beat):beat/2;}public static double Beats(Montage m,double seconds,double at=0){return Beat(m,at+seconds)-Beat(m,at);}public static double Seconds(Montage m,double beats,double at=0){return Time(m,Beat(m,at)+beats)-at;}public static string Position(Montage m,double time){long tick=(long)Math.Round(Beat(m,time)*PPQ);long bar=(long)Math.Floor(tick/(4.0*PPQ));long within=tick-bar*4*PPQ;return "mesure "+(bar+1)+" · noire "+(within/PPQ+1)+" · tick "+(within%PPQ);}public static string Label(Montage m,double seconds,double at=0){return (Beats(m,seconds,at)/4).ToString("0.###")+" mesures";}public static bool IsTime(string title){return title.EndsWith("(ms)")||title.EndsWith(", ms")||title.EndsWith("(s)");}public static string Title(string title){return title.Replace("(ms)","").Replace(", ms","").Replace("(s)","").Trim();}public static Control Editor(Montage m,double seconds,double min,double max,Action<double> set,double at=0){return BeatsEditor(Beats(m,seconds,at),Beats(m,min,at),Beats(m,max,at),b=>set(Seconds(m,b,at)));}public static Control BeatsEditor(double value,double min,double max,Action<double> set){var panel=new FlowLayoutPanel{Width=350,Height=30,WrapContents=false};var unit=new ComboBox{Width=155,DropDownStyle=ComboBoxStyle.DropDownList};unit.Items.AddRange(new object[]{"Mesures","Blanches","Noires","Croches","Doubles croches","Triples croches","Quadruples croches","Ticks (96/noire)"});double[] factors={4,2,1,.5,.25,.125,.0625,1.0/PPQ};var number=UiR2.Number(value, -100000000,100000000,6);number.Width=150;bool updating=false;Action update=()=>{updating=true;double factor=factors[unit.SelectedIndex];number.Minimum=-100000000;number.Maximum=100000000;number.Value=(decimal)(value/factor);number.Increment=1;updating=false;};unit.SelectedIndex=2;unit.SelectedIndexChanged+=delegate{update();};number.ValueChanged+=delegate{if(updating)return;double next=(double)number.Value*factors[unit.SelectedIndex];if(next<min||next>max){update();return;}value=next;set(value);};update();panel.Controls.Add(number);panel.Controls.Add(unit);return panel;}}
}
